--
-- Table structure for table `complaints`
--

DROP TABLE IF EXISTS `complaints`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `complaints` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `assigned_to` bigint unsigned DEFAULT NULL,
  `title` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resolution_notes` text COLLATE utf8mb4_unicode_ci,
  `resolved_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `complaints_user_id_foreign` (`user_id`),
  KEY `complaints_assigned_to_foreign` (`assigned_to`),
  CONSTRAINT `complaints_assigned_to_foreign` FOREIGN KEY (`assigned_to`) REFERENCES `employees` (`id`) ON DELETE SET NULL,
  CONSTRAINT `complaints_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=185 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `complaints`
--

LOCK TABLES `complaints` WRITE;
/*!40000 ALTER TABLE `complaints` DISABLE KEYS */;
INSERT INTO `complaints` VALUES (23,367,NULL,'تعارض تقارير الغياب — يحتاج تحقيقاً','═══════════════════════════════════════════\n تعارض تقارير الغياب — شكوى تلقائية\n═══════════════════════════════════════════\n\nضغط كلا الطرفين زر الغياب خلال نافذة ساعتين.\nلم تُطبَّق أي عقوبة تلقائية. يُرجى التحقيق وتطبيق العقوبة يدوياً.\n\n── تفاصيل الرحلة ─────────────────────────\n  رقم الرحلة    : #110\n  من            : Test Pickup — Damascus\n  إلى           : Test Destination — Aleppo\n  موعد الانطلاق: 2026-08-20 00:48\n  طريقة الدفع  : cash\n\n── الأطراف ────────────────────────────────\n  السائق  : NS Driver 4 (ID: 366)\n  الراكب  : NS Passenger 4 (ID: 367)\n  رقم الحجز: #119 — 1 مقعد\n\n── التسلسل الزمني ─────────────────────────\n  أول تقرير : الراكب — 2026-08-20 02:48:30\n  ثاني تقرير: السائق — 2026-08-20 02:48:30 (هذا التقرير)\n  نافذة النزاع: 2026-08-20 04:48:30\n\n── المطلوب من فريق الدعم ──────────────────\n  1. التحقق من سجلات الموقع / وقت دخول التطبيق\n  2. التواصل مع الطرفين إن لزم\n  3. تطبيق العقوبة على الطرف المخطئ يدوياً','no_show','pending',NULL,NULL,'2026-08-20 02:48:30','2026-08-20 02:48:30'),(24,369,NULL,'تعارض تقارير الغياب — يحتاج تحقيقاً','═══════════════════════════════════════════\n تعارض تقارير الغياب — شكوى تلقائية\n═══════════════════════════════════════════\n\nضغط كلا الطرفين زر الغياب خلال نافذة ساعتين.\nلم تُطبَّق أي عقوبة تلقائية. يُرجى التحقيق وتطبيق العقوبة يدوياً.\n\n── تفاصيل الرحلة ─────────────────────────\n  رقم الرحلة    : #111\n  من            : Test Pickup — Damascus\n  إلى           : Test Destination — Aleppo\n  موعد الانطلاق: 2026-08-20 00:48\n  طريقة الدفع  : cash\n\n── الأطراف ────────────────────────────────\n  السائق  : NS Driver 5 (ID: 368)\n  الراكب  : NS Passenger 5 (ID: 369)\n  رقم الحجز: #120 — 1 مقعد\n\n── التسلسل الزمني ─────────────────────────\n  أول تقرير : الراكب — 2026-08-20 02:48:30\n  ثاني تقرير: السائق — 2026-08-20 02:48:30 (هذا التقرير)\n  نافذة النزاع: 2026-08-20 04:48:30\n\n── المطلوب من فريق الدعم ─────────