DROP TABLE IF EXISTS `profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `profiles` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `profile_photo` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `full_name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gender` enum('M','F') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `number_of_rides` int NOT NULL DEFAULT '0',
  `description` text COLLATE utf8mb4_unicode_ci,
  `car_pic` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `type_of_car` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color_of_car` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `number_of_seats` int DEFAULT NULL,
  `face_id_pic` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `back_id_pic` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `driving_license_pic` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mechanic_card_pic` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `radio` tinyint(1) DEFAULT NULL,
  `smoking` tinyint(1) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `profiles_user_id_foreign` (`user_id`),
  CONSTRAINT `profiles_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2538 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

