--
-- Table structure for table `rides`
--

DROP TABLE IF EXISTS `rides`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rides` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `driver_id` bigint unsigned NOT NULL,
  `pickup_address` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pickup_lat` decimal(10,8) DEFAULT NULL,
  `pickup_lng` decimal(11,8) DEFAULT NULL,
  `destination_address` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `destination_lat` decimal(10,8) DEFAULT NULL,
  `destination_lng` decimal(11,8) DEFAULT NULL,
  `pickup_location` geometry NOT NULL,
  `destination_location` geometry NOT NULL,
  `distance` int unsigned NOT NULL COMMENT 'Meters',
  `duration` int unsigned NOT NULL COMMENT 'Seconds',
  `route_geometry` json DEFAULT NULL,
  `chosen_route_index` smallint unsigned NOT NULL DEFAULT '0' COMMENT 'Index of selected route from alternatives',
  `departure_time` datetime NOT NULL,
  `finished_at` timestamp NULL DEFAULT NULL,
  `driver_confirmed_at` timestamp NULL DEFAULT NULL,
  `passengers_confirmed` tinyint(1) NOT NULL DEFAULT '0',
  `available_seats` smallint unsigned NOT NULL,
  `price_per_seat` decimal(8,2) NOT NULL,
  `vehicle_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payment_method` enum('cash','e-pay') COLLATE utf8mb4_unicode_ci NOT NULL,
  `booking_type` enum('direct','request') COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `communication_number` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cash_creation_fee` decimal(15,2) DEFAULT NULL,
  `cash_fee_deferred` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rides_departure_time_available_seats_index` (`departure_time`,`available_seats`),
  KEY `rides_status_departure_seats_index` (`status`,`departure_time`,`available_seats`),
  KEY `rides_driver_status_index` (`driver_id`,`status`),
  CONSTRAINT `rides_driver_id_foreign` FOREIGN KEY (`driver_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=790 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `rides`
--

