DROP TABLE IF EXISTS `user_ratings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_ratings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `rater_id` bigint unsigned DEFAULT NULL,
  `rated_user_id` bigint unsigned NOT NULL,
  `rating` decimal(2,1) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `ride_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rating_rater_rated_ride` (`rater_id`,`rated_user_id`,`ride_id`),
  KEY `user_ratings_rated_user_id_index` (`rated_user_id`),
  KEY `user_ratings_rater_id_index` (`rater_id`),
  KEY `fk_ur_ride_id` (`ride_id`),
  CONSTRAINT `fk_ur_ride_id` FOREIGN KEY (`ride_id`) REFERENCES `rides` (`id`) ON DELETE SET NULL,
  CONSTRAINT `user_ratings_rated_user_id_foreign` FOREIGN KEY (`rated_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `user_ratings_rater_id_foreign` FOREIGN KEY (`rater_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1744 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

